{
  "story": "A robot arm follows a precise sequence to pick up an object, moving from sensing to grasping.",
  "aha": {
    "stateId": "grip",
    "observation": "Closing the end effector securely around the object completes the physical grasp."
  },
  "layout": {
    "preset": "default",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.step",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "label": "Step",
      "options": ["sense", "approach", "align", "grip"]
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Pick and Place",
        "regions": [
          {
            "id": "sensor",
            "label": "Vision Sensor",
            "kind": "sensor"
          },
          {
            "id": "arm",
            "label": "Arm Joints",
            "kind": "actuator"
          },
          {
            "id": "gripper",
            "label": "End Effector",
            "kind": "gripper"
          }
        ],
        "states": [
          {
            "id": "sense",
            "label": "Sense",
            "short": "Detect",
            "sentence": "The camera locates the target object.",
            "why": "Object position must be known.",
            "active": ["sensor"],
            "calloutRegion": "sensor",
            "readouts": [
              {
                "id": "x",
                "label": "X Coord",
                "value": "120 mm"
              }
            ]
          },
          {
            "id": "approach",
            "label": "Approach",
            "short": "Move",
            "sentence": "Joints move the arm above the target.",
            "why": "Arm must reach the workspace.",
            "active": ["arm"],
            "calloutRegion": "arm",
            "readouts": [
              {
                "id": "h",
                "label": "Height",
                "value": "50 mm"
              }
            ]
          },
          {
            "id": "align",
            "label": "Align",
            "short": "Position",
            "sentence": "The gripper matches the object orientation.",
            "why": "Prevents collision during contact.",
            "active": ["arm", "gripper"],
            "calloutRegion": "gripper",
            "readouts": [
              {
                "id": "ang",
                "label": "Angle",
                "value": "0 deg"
              }
            ]
          },
          {
            "id": "grip",
            "label": "Grip",
            "short": "Clasp",
            "sentence": "Fingers close and lift the object.",
            "why": "Secure friction grasp is achieved.",
            "active": ["gripper"],
            "calloutRegion": "gripper",
              "readouts": [
              {
                "id": "force",
                "label": "Force",
                "value": "15 N"
              }
            ]
          }
        ]
      }
    ]
  }
}
